    @Test
    void rejectsReservationWithNoIdentification() throws Exception {
        String noIdJson = """
                {"roomNumber": 101, "guestName": "Ana Souza", "guestEmail": "ana@example.com",
                 "checkIn": "2027-07-10", "checkOut": "2027-07-11", "guests": 1, "ratePlan": "STANDARD"}
                """;

        HttpResponse<String> response = post("/reservations", noIdJson);
