        Guest company = Guest.withCompany("Carlos Silva", "carlos@example.com", "12.345.678/0001-90", "Tecnosul Ltda");
        Reservation reservation = service.create(
                new NewReservation(201, company, LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-12"), 2,
